{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": [
        "C27"
      ],
      "claim": "Tasimelteon, a structurally related melatonin receptor agonist, has an absolute oral bioavailability of 38.33% (90% CI 26.94–54.33%) in humans, which is above the 20% threshold; however, this evidence is not transferable to the query because tasimelteon lacks the fused indeno-furan scaffold that confers extensive first-pass metabolism in ramelteon.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is ramelteon, whose absolute oral bioavailability is approximately 1.8% in humans due to extensive first-pass metabolism, well below the 20% threshold. The closest analogue tasimelteon has higher F (38%), but its different ring system and metabolic stability make that result non-transferable; therefore the prediction is low.",
  "evidence_gaps": [
    "No direct human absolute bioavailability record for ramelteon was included in the evidence set.",
    "The only close analogue (tasimelteon) has a different metabolic profile, so its F cannot be directly extrapolated.",
    "Lack of records for ramelteon's first-pass metabolism or CYP-mediated clearance."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

